import { describe, test, expect } from "bun:test";
import { validateJson } from "./validate-json";

describe("validateJson", () => {
  test("returns success for valid JSON object", () => {
    const result = validateJson('{"name": "test", "value": 123}');
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("returns success for valid JSON array", () => {
    const result = validateJson('[1, 2, 3, "test"]');
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("returns success for valid JSON primitives", () => {
    expect(validateJson('"string"').valid).toBe(true);
    expect(validateJson("123").valid).toBe(true);
    expect(validateJson("true").valid).toBe(true);
    expect(validateJson("null").valid).toBe(true);
  });

  test("returns error for invalid JSON syntax", () => {
    const result = validateJson('{"invalid": }');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns error for malformed JSON", () => {
    const result = validateJson("{not valid json}");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns error for empty input", () => {
    const result = validateJson("");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns error for unclosed structures", () => {
    const result = validateJson('{"key": "value"');
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });
});

#!/usr/bin/env bun

export interface ValidationResult {
  valid: boolean;
  error?: string;
}

export function validateJson(input: string): ValidationResult {
  try {
    JSON.parse(input);
    return { valid: true };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : "Unknown error";
    return { valid: false, error: errorMessage };
  }
}

async function main(): Promise<void> {
  try {
    const input = await Bun.stdin.text();
    const result = validateJson(input);

    if (result.valid) {
      console.log("Valid JSON");
      process.exit(0);
    } else {
      console.error(`Invalid JSON: ${result.error}`);
      process.exit(1);
    }
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : "Unknown error";
    console.error(`Error reading input: ${errorMessage}`);
    process.exit(1);
  }
}

if (import.meta.main) {
  main();
}

