/**
 * Add two numbers.
 */
export function add(a: number, b: number): number {
  return a + b;
}

/**
 * Generate a time-based greeting message.
 * Returns "Good morning", "Good afternoon", or "Good evening" based on the hour.
 * @param name - The name of the person to greet
 * @param hour - The hour of the day (0-23)
 * @returns A time-appropriate greeting message
 */
export function getTimeBasedGreeting(name: string, hour: number): string {
  if (hour < 12) {
    return `Good morning, ${name}!`;
  } else if (hour < 18) {
    return `Good afternoon, ${name}!`;
  } else {
    return `Good evening, ${name}!`;
  }
}

