type JsonPrimitive = string | number | boolean | null;

/**
 * Any valid JSON value.
 */
type JsonValue = JsonPrimitive | JsonValue[] | { [key: string]: JsonValue };

/**
 * Supported schema types for validation.
 */
type SchemaType = "string" | "number" | "boolean" | "null" | "array" | "object";

/**
 * JSON schema definition for validation.
 *
 * @property type - The expected type of the value
 * @property properties - For object types, defines the schema for each property
 * @property required - For object types, lists required property names
 * @property items - For array types, defines the schema for array items
 */
interface Schema {
  type: SchemaType;
  properties?: { [key: string]: Schema };
  required?: string[];
  items?: Schema;
}

/**
 * Result of JSON validation.
 *
 * @property valid - True if validation passed, false otherwise
 * @property errors - Array of error messages if validation failed
 */
interface ValidationResult {
  valid: boolean;
  errors?: string[];
}

/**
 * Creates a schema definition for JSON validation.
 *
 * This is a helper function that provides type safety and clarity when defining schemas.
 *
 * @param schema - The schema definition
 * @returns The same schema, typed correctly
 *
 * @example
 * ```typescript
 * const userSchema = createSchema({
 *   type: "object",
 *   properties: {
 *     name: { type: "string" },
 *     age: { type: "number" },
 *     email: { type: "string" }
 *   },
 *   required: ["name", "age"]
 * });
 * ```
 *
 * @example
 * ```typescript
 * const arraySchema = createSchema({
 *   type: "array",
 *   items: { type: "number" }
 * });
 * ```
 */
export function createSchema(schema: Schema): Schema {
  return schema;
}

