/**
 * Utility functions for the eval test project.
 */

/**
 * Greet someone by name.
 */
export function greet(name: string): string {
  return `Hello, ${name}!`;
}

/**
 * Add two numbers.
 */
export function add(a: number, b: number): number {
  return a + b;
}

type JsonPrimitive = string | number | boolean | null;
type JsonValue = JsonPrimitive | JsonValue[] | { [key: string]: JsonValue };

type SchemaType = "string" | "number" | "boolean" | "null" | "array" | "object";

interface Schema {
  type: SchemaType;
  properties?: { [key: string]: Schema };
  required?: string[];
  items?: Schema;
}

interface ValidationResult {
  valid: boolean;
  errors?: string[];
}

export function createSchema(schema: Schema): Schema {
  return schema;
}

export function validateJson(data: unknown, schema: Schema): ValidationResult {
  const errors: string[] = [];

  function validate(value: unknown, currentSchema: Schema, path = "root"): boolean {
    const actualType = getType(value);

    if (actualType !== currentSchema.type) {
      errors.push(`${path}: expected ${currentSchema.type}, got ${actualType}`);
      return false;
    }

    if (currentSchema.type === "object" && typeof value === "object" && value !== null) {
      const obj = value as { [key: string]: unknown };

      if (currentSchema.required) {
        for (const requiredField of currentSchema.required) {
          if (!(requiredField in obj)) {
            errors.push(`${path}: missing required field "${requiredField}"`);
            return false;
          }
        }
      }

      if (currentSchema.properties) {
        for (const [key, propSchema] of Object.entries(currentSchema.properties)) {
          if (key in obj) {
            const isValid = validate(obj[key], propSchema, `${path}.${key}`);
            if (!isValid) {
              return false;
            }
          }
        }
      }
    }

    if (currentSchema.type === "array" && Array.isArray(value) && currentSchema.items) {
      for (let i = 0; i < value.length; i++) {
        const isValid = validate(value[i], currentSchema.items, `${path}[${i}]`);
        if (!isValid) {
          return false;
        }
      }
    }

    return true;
  }

  function getType(value: unknown): string {
    if (value === null) return "null";
    if (Array.isArray(value)) return "array";
    return typeof value;
  }

  const valid = validate(data, schema);

  return valid ? { valid: true } : { valid: false, errors };
}

